import asyncio
class _pf_Async:
    __slots__ = ("fn", "args")
    def __init__(self, fn, *args):
        self.fn = fn
        self.args = args
    def __await__(self):
        return self.fn(*self.args).__await__()
    async def __call__(self):
        return await self
    def __repr__(self):
        return "<Async>"
def _pf_async_sleep(secs):
    return _pf_Async(asyncio.sleep, secs)
async def _pf_run(a):
    return await a
nap = _pf_async_sleep
async def _pf_fn0():
    await nap(0.0)
    return "woke"
main = _pf_Async(_pf_fn0)
print(asyncio.run(_pf_run(main)))
